import type {
  MedusaRequest,
  MedusaResponse,
} from "@medusajs/framework/http"
import { createStoresWorkflow } from "@medusajs/medusa/core-flows"

export async function POST(
  req: MedusaRequest,
  res: MedusaResponse
) {
  const { result } = await createStoresWorkflow(req.scope)
    .run({
      input: {
        stores: [{
          name: "Acme",
          supported_currencies: [{
            currency_code: "usd",
            is_default: true
          }]
        }]
      }
    })

  res.send(result)
}

